       '{"elementos":9,"cuentas":1628,"porDigitos":{"2":77,"3":311,"4":641,"5":587,"6":12},"sha256":"48c568ca196c68348743dda96c55c38593b0437ce732a4c5d77d7c9aca896b19","erratasDocumentadas":1}'::jsonb,
       'sistema'
FROM version_pcge WHERE codigo = 'PCGE_2026';

DO $$
DECLARE
    n_cuentas   INTEGER;
    n_elementos INTEGER;
    n_huerfanas INTEGER;
BEGIN
    SELECT count(*) INTO n_cuentas FROM cuenta_contable c JOIN version_pcge v ON v.id = c.version_id WHERE v.codigo = 'PCGE_2026';
    SELECT count(*) INTO n_elementos FROM elemento_contable e JOIN version_pcge v ON v.id = e.version_id WHERE v.codigo = 'PCGE_2026';
    SELECT count(*) INTO n_huerfanas FROM cuenta_contable c JOIN version_pcge v ON v.id = c.version_id
     WHERE v.codigo = 'PCGE_2026' AND c.nivel > 2 AND c.padre_id IS NULL;
    IF n_cuentas <> 1628 OR n_elementos <> 9 OR n_huerfanas <> 0 THEN
        RAISE EXCEPTION 'Verificación fallida en PCGE_2026: % cuentas, % elementos, % huérfanas', n_cuentas, n_elementos, n_huerfanas;
    END IF;
END $$;
